test_suite:
function testSignal<T>(initial: T) {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next: T) => { value = next; listeners.forEach(fn => fn()); },
    subscribe: (fn: () => void) => { listeners.add(fn); return () => { listeners.delete(fn); }; },
  };
}

test('returns computed value based on signal values', () => {
  const a = testSignal(2);
  const b = testSignal(3);
  const { result } = renderHook(() => useComputed(() => a.get() + b.get(), [a, b]));
  expect(result.current).toBe(5);
});

test('updates when a signal changes', () => {
  const sig = testSignal(10);
  const { result } = renderHook(() => useComputed(() => sig.get() * 2, [sig]));
  act(() => sig.set(20));
  expect(result.current).toBe(40);
});

test('depends on multiple signals', () => {
  const x = testSignal(1);
  const y = testSignal(2);
  const z = testSignal(3);
  const { result } = renderHook(() => useComputed(() => x.get() + y.get() + z.get(), [x, y, z]));
  act(() => y.set(10));
  expect(result.current).toBe(14);
});

test('computes string concatenation from signals', () => {
  const first = testSignal('Hello');
  const last = testSignal('World');
  const { result } = renderHook(() =>
    useComputed(() => `${first.get()} ${last.get()}`, [first, last])
  );
  expect(result.current).toBe('Hello World');
});

// __hidden__
test('updating one signal does not affect unrelated computed', () => {
  const a = testSignal(5);
  const b = testSignal(10);
  const { result: ra } = renderHook(() => useComputed(() => a.get() * 2, [a]));
  act(() => b.set(99));
  expect(ra.current).toBe(10);
});

solution:
import { useSyncExternalStore, useCallback, useRef } from 'react';

type Signal<T> = {
  get: () => T;
  set: (v: T) => void;
  subscribe: (fn: () => void) => () => void;
};

export function useComputed<T>(
  compute: () => T,
  signals: Signal<any>[]
): T {
  const computeRef = useRef(compute);
  computeRef.current = compute;

  const subscribe = useCallback((notify: () => void) => {
    const unsubs = signals.map(s => s.subscribe(notify));
    return () => unsubs.forEach(fn => fn());
  }, signals);

  const getSnapshot = useCallback(() => computeRef.current(), signals);

  return useSyncExternalStore(subscribe, getSnapshot);
}
